{
  "findings": [
    {
      "check_id": "CKV_AWS_79",
      "title": "Ensure Instance Metadata Service Version 1 is not enabled",
      "resource": "aws_launch_configuration.levelup-launchconfig",
      "severity": "MEDIUM",
      "explanation": "Instance Metadata Service Version 1 is enabled by default, which can be used to obtain instance metadata without requiring a token, potentially allowing unauthorized access to instance metadata."
    },
    {
      "check_id": "CKV_AWS_8",
      "title": "Ensure all data stored in the Launch configuration or instance Elastic Blocks Store is securely encrypted",
      "resource": "aws_launch_configuration.levelup-launchconfig",
      "severity": "MEDIUM",
      "explanation": "The launch configuration does not specify encryption for the root block device, potentially leaving data stored on the instance's root volume unencrypted."
    }
  ],
  "patched_code": "resource \"aws_launch_configuration\" \"levelup-launchconfig\" {\n  name_prefix     = \"levelup-launchconfig\"\n  image_id        = lookup(var.AMIS, var.AWS_REGION)\n  instance_type   = \"t2.micro\"\n  key_name        = aws_key_pair.levelup_key.key_name\n  metadata_options {\n    http_tokens = \"required\"\n  }\n  root_block_device {\n    encrypted = true\n  }\n}",
  "fix_summary": "Added metadata_options to disable IMDSv1 and root_block_device to enable encryption for the root volume."
}
